import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import {fileURLToPath} from 'node:url';

function validateRoot(root) {
  if (typeof root !== 'string' || root.length === 0) throw Error('root must be a path');
  const parsedRoot = path.parse(root).root;
  let checkedRoot = root;
  while (checkedRoot.length > parsedRoot.length && checkedRoot.endsWith(path.sep)) {
    checkedRoot = checkedRoot.slice(0, -1);
  }
  const stat = fs.lstatSync(checkedRoot);
  if (!stat.isDirectory() || stat.isSymbolicLink()) throw Error('root must be a non-symlink directory');
}
function validatePath(selected) {
  if (typeof selected !== 'string' || !selected || selected.startsWith('/')
    || selected.includes('\\') || selected.includes('\0')
    || selected.split('/').some(part => !part || part === '.' || part === '..')) throw Error('invalid selected path');
}
function inspect(root, selected) {
  const parts = selected.split('/'); let current = root;
  for (let i = 0; i < parts.length; i++) {
    current = path.join(current, parts[i]);
    let stat;
    try { stat = fs.lstatSync(current); }
    catch (error) { if (error.code === 'ENOENT') return {kind:'missing'}; throw error; }
    if (stat.isSymbolicLink() || (i === parts.length - 1 ? !stat.isFile() : !stat.isDirectory())) return {kind:'unsafe'};
    if (i === parts.length - 1) {
      const bytes = fs.readFileSync(current);
      return {kind:'file',sha256:crypto.createHash('sha256').update(bytes).digest('hex'),size:bytes.length,mode:stat.mode & 0o777};
    }
  }
}

function compareStrings(left, right) {
  return left < right ? -1 : left > right ? 1 : 0;
}

function validateManifest(manifest) {
  if (manifest === null || typeof manifest !== 'object' || Array.isArray(manifest)) {
    throw Error('manifest must be an object');
  }
  if (manifest.version !== 1) throw Error('unsupported manifest version');
  if (!Array.isArray(manifest.files)) throw Error('manifest files must be an array');

  const seen = new Set();
  return manifest.files.map(entry => {
    if (entry === null || typeof entry !== 'object' || Array.isArray(entry)) {
      throw Error('manifest file entry must be an object');
    }
    validatePath(entry.path);
    if (seen.has(entry.path)) throw Error('duplicate manifest path');
    seen.add(entry.path);
    if (typeof entry.sha256 !== 'string' || !/^[0-9a-f]{64}$/.test(entry.sha256)) {
      throw Error('invalid manifest sha256');
    }
    if (!Number.isSafeInteger(entry.size) || entry.size < 0) {
      throw Error('invalid manifest size');
    }
    if (!Number.isInteger(entry.mode) || entry.mode < 0 || entry.mode > 0o777) {
      throw Error('invalid manifest mode');
    }
    return {path:entry.path,sha256:entry.sha256,size:entry.size,mode:entry.mode};
  });
}

export function createManifest(root, paths) {
  validateRoot(root);
  if (!Array.isArray(paths)) throw Error('paths must be an array');
  const seen = new Set();
  for (const selected of paths) {
    validatePath(selected);
    if (seen.has(selected)) throw Error('duplicate selection');
    seen.add(selected);
  }
  return {version:1,files:[...paths].sort(compareStrings).map(selected => {
    const current = inspect(root, selected);
    if (current.kind !== 'file') throw Error(`${current.kind} selected path`);
    return {path:selected,sha256:current.sha256,size:current.size,mode:current.mode};
  })};
}

export function verifyManifest(root, manifest) {
  const entries = validateManifest(manifest);
  validateRoot(root);

  const report = {ok:true,unchanged:[],changed:[],missing:[],unsafe:[]};
  for (const entry of entries) {
    const current = inspect(root, entry.path);
    if (current.kind === 'missing') {
      report.missing.push(entry.path);
    } else if (current.kind === 'unsafe') {
      report.unsafe.push(entry.path);
    } else {
      const reasons = [];
      if (current.sha256 !== entry.sha256 || current.size !== entry.size) reasons.push('content');
      if (current.mode !== entry.mode) reasons.push('mode');
      if (reasons.length === 0) report.unchanged.push(entry.path);
      else report.changed.push({path:entry.path,reasons});
    }
  }

  report.unchanged.sort(compareStrings);
  report.changed.sort((left, right) => compareStrings(left.path, right.path));
  report.missing.sort(compareStrings);
  report.unsafe.sort(compareStrings);
  report.ok = report.changed.length === 0 && report.missing.length === 0 && report.unsafe.length === 0;
  return report;
}

function runCli(argv) {
  const [command, root, ...args] = argv;
  if (command === 'create' && root !== undefined) {
    return {value:createManifest(root, args),exitCode:0};
