  report.changed.sort((left, right) => compareStrings(left.path, right.path));
  report.missing.sort(compareStrings);
  report.unsafe.sort(compareStrings);
  report.ok = report.changed.length === 0 && report.missing.length === 0 && report.unsafe.length === 0;
  return report;
}

