import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import crypto from 'node:crypto';
import {spawnSync} from 'node:child_process';
import {fileURLToPath} from 'node:url';
import * as snapshot from '../snapshot.js';
const snapshotScript = fileURLToPath(new URL('../snapshot.js', import.meta.url));
function fixture(t) {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(),'snapshot-public-'));
  fs.writeFileSync(path.join(dir,'a.txt'),'abc'); fs.chmodSync(path.join(dir,'a.txt'),0o640);
  t.after(() => fs.rmSync(dir,{recursive:true,force:true})); return dir;
}
test('existing builder hashes exact bytes and permission bits', t => {
  const root = fixture(t);
  assert.deepEqual(snapshot.createManifest(root,['a.txt']),{version:1,files:[{
    path:'a.txt',sha256:crypto.createHash('sha256').update('abc').digest('hex'),size:3,mode:0o640,
  }]});
});
test('new verifier reports unchanged, content and missing', t => {
  const root = fixture(t), manifest = snapshot.createManifest(root,['a.txt']);
  assert.deepEqual(snapshot.verifyManifest(root,manifest),{ok:true,unchanged:['a.txt'],changed:[],missing:[],unsafe:[]});
  fs.writeFileSync(path.join(root,'a.txt'),'xyz');
  assert.deepEqual(snapshot.verifyManifest(root,manifest).changed,[{path:'a.txt',reasons:['content']}]);
  fs.unlinkSync(path.join(root,'a.txt'));
  assert.deepEqual(snapshot.verifyManifest(root,manifest).missing,['a.txt']);
});
test('unsafe selections and invalid manifests throw', t => {
  const root = fixture(t);
  assert.throws(() => snapshot.createManifest(root,['../outside']));
  assert.throws(() => snapshot.verifyManifest(root,{version:2,files:[]}));
});

test('verifier sorts every category and reports only differing properties', t => {
  const root = fixture(t);
  fs.writeFileSync(path.join(root,'b.txt'),'before');
  fs.writeFileSync(path.join(root,'c.txt'),'remove');
  fs.writeFileSync(path.join(root,'d.txt'),'replace');
  const manifest = snapshot.createManifest(root,['d.txt','c.txt','b.txt','a.txt']);
  manifest.files.reverse();

  fs.writeFileSync(path.join(root,'b.txt'),'after');
  fs.chmodSync(path.join(root,'b.txt'),0o600);
  fs.unlinkSync(path.join(root,'c.txt'));
  fs.unlinkSync(path.join(root,'d.txt'));
  fs.mkdirSync(path.join(root,'d.txt'));

  assert.deepEqual(snapshot.verifyManifest(root,manifest),{
    ok:false,
    unchanged:['a.txt'],
    changed:[{path:'b.txt',reasons:['content','mode']}],
    missing:['c.txt'],
    unsafe:['d.txt'],
  });
});

test('symlinks and non-directory intermediate components are unsafe', t => {
  const root = fixture(t);
  fs.symlinkSync('a.txt',path.join(root,'link'));
  const base = snapshot.createManifest(root,['a.txt']).files[0];
  const makeEntry = selected => ({...base,path:selected});
  const manifest = {version:1,files:[makeEntry('link'),makeEntry('a.txt/child')]};
  assert.deepEqual(snapshot.verifyManifest(root,manifest).unsafe,['a.txt/child','link']);
});

test('manifest validation is strict and does not mutate inputs', t => {
  const root = fixture(t);
  const valid = snapshot.createManifest(root,['a.txt']);
  const before = structuredClone(valid);
  snapshot.verifyManifest(root,valid);
  assert.deepEqual(valid,before);

  for (const manifest of [
    null, [], {version:1,files:{}},
    {version:1,files:[null]},
    {version:1,files:[{...valid.files[0],path:'a//b'}]},
    {version:1,files:[valid.files[0],valid.files[0]]},
    {version:1,files:[{...valid.files[0],sha256:'A'.repeat(64)}]},
    {version:1,files:[{...valid.files[0],size:Number.MAX_SAFE_INTEGER + 1}]},
    {version:1,files:[{...valid.files[0],mode:512}]},
  ]) assert.throws(() => snapshot.verifyManifest(root,manifest));
});

test('CLI emits JSON and uses exit status 0, 1, or 2', t => {
  const root = fixture(t);
  const created = spawnSync(process.execPath,[snapshotScript,'create',root,'a.txt'],{encoding:'utf8'});
  assert.equal(created.status,0);
  assert.equal(created.stderr,'');
  const manifestFile = path.join(root,'manifest.json');
  fs.writeFileSync(manifestFile,created.stdout);

  const verified = spawnSync(process.execPath,[snapshotScript,'verify',root,manifestFile],{encoding:'utf8'});
  assert.equal(verified.status,0);
  assert.equal(verified.stderr,'');
  assert.equal(JSON.parse(verified.stdout).ok,true);

  fs.writeFileSync(path.join(root,'a.txt'),'changed');
  const drifted = spawnSync(process.execPath,[snapshotScript,'verify',root,manifestFile],{encoding:'utf8'});
  assert.equal(drifted.status,1);
  assert.equal(drifted.stderr,'');
  assert.equal(JSON.parse(drifted.stdout).ok,false);

  const invalid = spawnSync(process.execPath,[snapshotScript,'verify',root],{encoding:'utf8'});
  assert.equal(invalid.status,2);
  assert.equal(invalid.stdout,'');
  assert.notEqual(invalid.stderr,'');
});

